window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-621645b35d6a1995"]={"versions": [{"id": "FIG-621645b35d6a1995", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung eines algorithmischen Einzelschritts innerhalb der End-to-End-Kommunikationsabsicherung (AUTOSAR E2E Protocol, Profil 4m). Das Diagramm spezifiziert die Serialisierung des Längenfelds im Rahmen der Sender- und Weiterleitungsfunktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontext-Aktionen / Funktionen (Call Behavior Actions / Deklarationsblöcke)</strong>:</li>\n<li><code>E2E_P04mProtect</code>: Schutzfunktion des Profils 4m zur Erzeugung von E2E-Kontrolldaten.</li>\n<li><code>E2E_P04mForward</code>: Weiterleitungsfunktion für Profile 4m bei Gateway- bzw. Forwarding-Szenarien.</li>\n<li><strong>Aktivitätsknoten (Action)</strong>:</li>\n<li><code>Copy 2-byte Length on bytes Data[Offset...Offset+1] in Big Endian order</code>: Spezifischer Verarbeitungsschritt zur Platzierung der Nutzdatenlänge.</li>\n<li><strong>Steuerknoten</strong>:</li>\n<li>Initialknoten (ausgefüllter Kreis).</li>\n<li>Aktivitätsendknoten (umrandeter Punkt / Bullseye).</li>\n<li><strong>Daten-/Parameterbezüge</strong>:</li>\n<li><code>Length</code>: 2-Byte-Längenwert der serialisierten Daten.</li>\n<li><code>Data[]</code>: Byte-Array des zu übertragenden Datenpuffers.</li>\n<li><code>Offset</code>: Byte-Position innerhalb des Datenpuffers, ab der der E2E-Header bzw. das Längenfeld geschrieben wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Ausführung beginnt am Initialknoten beim Aufruf des Teilschritts „Write Length“ innerhalb von <code>E2E_P04mProtect()</code> bzw. <code>E2E_P04mForward()</code>.</li>\n<li>Über einen Kontrollfluss wird die Aktion ausgeführt: Ein 2 Byte breiter Längenwert (<code>Length</code>) wird in Big-Endian-Byte-Reihenfolge in das Array <code>Data</code> an den Indexpositionen <code>Offset</code> und <code>Offset+1</code> geschrieben (<code>Data[Offset...Offset+1]</code>).</li>\n<li>Nach Abschluss des Schreibvorgangs wechselt der Kontrollfluss zum Aktivitätsendknoten und beendet diesen Teilschritt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Teilschritt definiert normativ das exakte Byte-Layout und die Bytereihenfolge (Network Byte Order / Big Endian) für das Längenfeld des E2E-Profils 4m. Entwickler müssen sicherstellen, dass das 16-Bit-Feld <code>Length</code> an die durch die Konfiguration vorgegebene Offset-Adresse serialisiert wird, bevor Folgeschritte (wie z. B. Counter- oder CRC-Berechnung) ausgeführt werden. Sowohl Sender als auch weiterleitende Komponenten müssen dieses Verhalten identisch implementieren.</p>"}, {"id": "FIG-c94872e17211955a", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung eines algorithmischen Einzelschritts innerhalb der End-to-End-Kommunikationsabsicherung (AUTOSAR E2E Protocol, Profil 4m). Das Diagramm spezifiziert die Serialisierung des Längenfelds im Rahmen der Sender- und Weiterleitungsfunktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontext-Aktionen / Funktionen (Call Behavior Actions / Deklarationsblöcke)</strong>:</li>\n<li><code>E2E_P04mProtect</code>: Schutzfunktion des Profils 4m zur Erzeugung von E2E-Kontrolldaten.</li>\n<li><code>E2E_P04mForward</code>: Weiterleitungsfunktion für Profile 4m bei Gateway- bzw. Forwarding-Szenarien.</li>\n<li><strong>Aktivitätsknoten (Action)</strong>:</li>\n<li><code>Copy 2-byte Length on bytes Data[Offset...Offset+1] in Big Endian order</code>: Spezifischer Verarbeitungsschritt zur Platzierung der Nutzdatenlänge.</li>\n<li><strong>Steuerknoten</strong>:</li>\n<li>Initialknoten (ausgefüllter Kreis).</li>\n<li>Aktivitätsendknoten (umrandeter Punkt / Bullseye).</li>\n<li><strong>Daten-/Parameterbezüge</strong>:</li>\n<li><code>Length</code>: 2-Byte-Längenwert der serialisierten Daten.</li>\n<li><code>Data[]</code>: Byte-Array des zu übertragenden Datenpuffers.</li>\n<li><code>Offset</code>: Byte-Position innerhalb des Datenpuffers, ab der der E2E-Header bzw. das Längenfeld geschrieben wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Ausführung beginnt am Initialknoten beim Aufruf des Teilschritts „Write Length“ innerhalb von <code>E2E_P04mProtect()</code> bzw. <code>E2E_P04mForward()</code>.</li>\n<li>Über einen Kontrollfluss wird die Aktion ausgeführt: Ein 2 Byte breiter Längenwert (<code>Length</code>) wird in Big-Endian-Byte-Reihenfolge in das Array <code>Data</code> an den Indexpositionen <code>Offset</code> und <code>Offset+1</code> geschrieben (<code>Data[Offset...Offset+1]</code>).</li>\n<li>Nach Abschluss des Schreibvorgangs wechselt der Kontrollfluss zum Aktivitätsendknoten und beendet diesen Teilschritt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Teilschritt definiert normativ das exakte Byte-Layout und die Bytereihenfolge (Network Byte Order / Big Endian) für das Längenfeld des E2E-Profils 4m. Entwickler müssen sicherstellen, dass das 16-Bit-Feld <code>Length</code> an die durch die Konfiguration vorgegebene Offset-Adresse serialisiert wird, bevor Folgeschritte (wie z. B. Counter- oder CRC-Berechnung) ausgeführt werden. Sowohl Sender als auch weiterleitende Komponenten müssen dieses Verhalten identisch implementieren.</p>"}], "trans": [{"from": "FIG-621645b35d6a1995", "to": "FIG-c94872e17211955a", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
